580	    private static func coordinate(fromObject object: [String: JSONValue]) -> CLLocationCoordinate2D? {
581	        let latitude = firstDouble(["lat", "latitude", "y", "gcj_lat", "gcjLat", "wgs_lat", "wgsLat"], in: object)
582	        let longitude = firstDouble(["lon", "lng", "longitude", "x", "gcj_lng", "gcjLng", "gcj_lon", "gcjLon", "wgs_lng", "wgsLng", "wgs_lon", "wgsLon"], in: object)
583	
584	        if let coordinate = coordinate(latitude: latitude, longitude: longitude) {
585	            return coordinate
586	        }
587	
588	        for key in ["location", "loc", "coordinate", "coordinates", "point", "gps"] {
589	            if let value = object[key] {
590	                let coordinates = trackCoordinates(from: value)
591	                if let first = coordinates.first {
592	                    return first
593	                }
594	            }
595	        }
596	
597	        return nil
598	    }
