600	    private static func coordinate(fromPair pair: [JSONValue]) -> CLLocationCoordinate2D? {
601	        guard pair.count >= 2,
602	              let first = pair[0].doubleValue,
603	              let second = pair[1].doubleValue else {
604	            return nil
605	        }
606	
607	        if abs(first) > 90, abs(second) <= 90 {
608	            return coordinate(latitude: second, longitude: first)
609	        }
610	
611	        return coordinate(latitude: first, longitude: second)
612	    }
