619	            return jsonCoordinates
620	        }
621	
622	        let separators = CharacterSet(charactersIn: ";|\n")
623	        let segments = trimmed.components(separatedBy: separators)
624	        let coordinates = segments.compactMap { segment -> CLLocationCoordinate2D? in
625	            let parts = segment
626	                .split { character in
627	                    character == "," || character == " " || character == "\t"
628	                }
629	                .compactMap { Double($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
630	            return coordinate(fromPair: parts.map { .number($0) })
631	        }
