967	    static func recalculatedDistanceMeters(from points: [NinebotRideTrackPoint]) -> Double {
968	        guard points.count > 1 else { return 0 }
969	        var total = 0.0
970	        var previous: CLLocation?
971	
972	        for point in points.sorted(by: { $0.date < $1.date }) {
973	            guard (-90...90).contains(point.latitude),
974	                  (-180...180).contains(point.longitude),
975	                  (point.horizontalAccuracy ?? 0) <= 120 else {
976	                continue
977	            }
978	
979	            let location = CLLocation(
980	                coordinate: CLLocationCoordinate2D(latitude: point.latitude, longitude: point.longitude),
981	                altitude: 0,
982	                horizontalAccuracy: max(point.horizontalAccuracy ?? 20, 1),
983	                verticalAccuracy: -1,
984	                timestamp: point.date
985	            )
986	
987	            if let previous {
988	                let deltaTime = location.timestamp.timeIntervalSince(previous.timestamp)
989	                let distance = location.distance(from: previous)
990	                if deltaTime >= 0,
991	                   deltaTime <= 30,
992	                   distance >= 0,
993	                   distance <= 300 {
994	                    total += distance
995	                }
996	            }
997	
998	            previous = location
999	        }
1000	
1001	        return total
1002	    }
