1914	    init(from decoder: Decoder) throws {
1915	        if let container = try? decoder.container(keyedBy: DynamicCodingKey.self) {
1916	            var object: [String: JSONValue] = [:]
1917	            for key in container.allKeys {
1918	                object[key.stringValue] = try container.decode(JSONValue.self, forKey: key)
1919	            }
