1932	
1933	        let container = try decoder.singleValueContainer()
1934	        if container.decodeNil() {
1935	            self = .null
1936	        } else if let value = try? container.decode(Bool.self) {
1937	            self = .bool(value)
1938	        } else if let value = try? container.decode(Double.self) {
